// Push gate: decides whether the agent may send a push to a user right now.
// Rules, checked in this order:
//   1. quiet hours, in the user's own time zone (can span midnight)
//   2. daily cap, counted per calendar day in the user's own time zone
// A blocked attempt is never counted. An allowed attempt counts as sent.

const HISTORY_KEEP_MS = 3 * 24 * 60 * 60 * 1000; // longer than any local day

const formatters = new Map();

function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Returns { day: "YYYY-MM-DD", minutes } in the given zone. Throws on a bad zone.
function localParts(date, timeZone) {
  const p = {};
  for (const { type, value } of formatterFor(timeZone).formatToParts(date)) p[type] = value;
  return {
    day: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseHHMM(s) {
  const m = typeof s === "string" ? /^([01]\d|2[0-3]):([0-5]\d)$/.exec(s) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

function inQuietHours(minutes, start, end) {
  if (start === end) return false; // empty window: quiet hours switched off
  if (start < end) return minutes >= start && minutes < end;
  return minutes >= start || minutes < end; // spans midnight
}

const deny = (reason) => ({ allowed: false, reason });

export function createPushGate() {
  const sent = new Map(); // user id -> array of send times (ms)

  return {
    attempt(user, now) {
      if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny("invalid_time");
      if (!user || typeof user.id !== "string" || user.id === "") return deny("invalid_settings");

      const start = parseHHMM(user.quietStart);
      const end = parseHHMM(user.quietEnd);
      const cap = user.dailyCap;
      if (start === null || end === null || !Number.isInteger(cap) || cap < 0) {
        return deny("invalid_settings");
      }

      let local;
      try {
        local = localParts(now, user.timeZone);
      } catch {
        return deny("invalid_settings"); // unknown time zone: fail closed
      }

      if (inQuietHours(local.minutes, start, end)) return deny("quiet_hours");

      const t = now.getTime();
      const history = (sent.get(user.id) ?? []).filter((x) => Math.abs(t - x) < HISTORY_KEEP_MS);
      const today = history.filter((x) => localParts(new Date(x), user.timeZone).day === local.day);

      if (today.length >= cap) {
        sent.set(user.id, history);
        return deny("daily_cap_reached");
      }

      history.push(t);
      sent.set(user.id, history);
      return { allowed: true, reason: null };
    },
  };
}

import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/courier-g2-2/bot.mjs";

const tokyo = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const d = (s) => new Date(s);

// Tokyo = UTC+9. 12:00 JST = 03:00Z
let g = createPushGate();
assert.deepEqual(g.attempt(tokyo, d("2026-03-10T03:00:00Z")), { allowed: true, reason: null });
// 22:00 JST = 13:00Z -> quiet (start inclusive); 06:59 JST = 21:59Z quiet; 07:00 JST = 22:00Z ok
assert.equal(g.attempt(tokyo, d("2026-03-10T13:00:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(tokyo, d("2026-03-10T21:59:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(tokyo, d("2026-03-10T22:00:00Z")).allowed, true); // 07:00 JST Mar 11 (new day)

// cap counts per local day; quiet-blocked attempts not counted
g = createPushGate();
for (let i = 0; i < 3; i++) assert.equal(g.attempt(tokyo, d(`2026-03-10T0${i}:00:00Z`)).allowed, true); // 09-11 JST
assert.equal(g.attempt(tokyo, d("2026-03-10T05:00:00Z")).reason, "daily_cap_reached");
// local midnight JST = 15:00Z; 23:00Z-ish is quiet; 07:00 JST Mar 11 = 22:00Z resets
assert.equal(g.attempt(tokyo, d("2026-03-10T22:00:00Z")).allowed, true);
// UTC-midnight is NOT the day boundary: 14:59Z Mar 10 is still Mar 10 JST
g = createPushGate();
const noQuiet = { ...tokyo, quietStart: "00:00", quietEnd: "00:00", dailyCap: 1 };
assert.equal(g.attempt(noQuiet, d("2026-03-10T14:59:00Z")).allowed, true);
assert.equal(g.attempt(noQuiet, d("2026-03-10T15:01:00Z")).allowed, true); // Mar 11 JST
assert.equal(g.attempt(noQuiet, d("2026-03-10T16:00:00Z")).reason, "daily_cap_reached");

// same-day window and users independent; per-call settings
g = createPushGate();
const day = { id: "u2", timeZone: "America/New_York", quietStart: "13:00", quietEnd: "15:00", dailyCap: 1 };
assert.equal(g.attempt(day, d("2026-07-01T17:30:00Z")).reason, "quiet_hours"); // 13:30 EDT
assert.equal(g.attempt(day, d("2026-07-01T16:00:00Z")).allowed, true); // 12:00 EDT
assert.equal(g.attempt(day, d("2026-07-01T20:00:00Z")).reason, "daily_cap_reached");
assert.equal(g.attempt({ ...day, dailyCap: 2 }, d("2026-07-01T20:00:00Z")).allowed, true);
assert.equal(g.attempt({ ...day, id: "other" }, d("2026-07-01T20:00:00Z")).allowed, true);

// DST: New York spring forward 2026-03-08; 03:30 EDT = 07:30Z
assert.equal(createPushGate().attempt({ ...day, quietStart: "02:00", quietEnd: "03:00" }, d("2026-03-08T07:30:00Z")).allowed, true);

// cap 0 and bad input
assert.equal(createPushGate().attempt({ ...tokyo, dailyCap: 0 }, d("2026-03-10T03:00:00Z")).reason, "daily_cap_reached");
assert.equal(createPushGate().attempt({ ...tokyo, timeZone: "Nope/Zone" }, d("2026-03-10T03:00:00Z")).reason, "invalid_settings");
assert.equal(createPushGate().attempt(tokyo, new Date("x")).reason, "invalid_time");
console.log("all ok");
